 "content": "def transform(grid):
    """Add a color-8 line just beyond the non-background object, continuing
    the orientation of the full color-2 reference line."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = g[0][0]

    # The reference is a complete row or column of color 2.
    ref = None
    for r, row in enumerate(g):
        if all(v == 2 for v in row):
            ref = ("row", r)
            break
    if ref is None:
        for c in range(w):
            if all(g[r][c] == 2 for r in range(h)):
                ref = ("col", c)
                break
    if ref is None:
        return g

    pts = [(r, c) for r in range(h) for c in range(w)
           if g[r][c] != bg and g[r][c] != 2]
    if not pts:
        return g
    min_r, max_r = min(r for r, c in pts), max(r for r, c in pts)
    min_c, max_c = min(c for r, c in pts), max(c for r, c in pts)

    if ref[0] == "row":
        rline = max_r + 1 if min_r > ref[1] else min_r - 1
        if 0 <= rline < h:
            g[rline] = [8] * w
    else:
        cline = max_c + 1 if min_c > ref[1] else min_c - 1
        if 0 <= cline < w:
            for r in range(h):
                g[r][cline] = 8
    return g
