 "content": "from collections import Counter


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    guide = 2
    bg = Counter(v for row in g for v in row if v != guide).most_common(1)[0][0]
    pts = [(r, c) for r in range(h) for c in range(w)
           if g[r][c] != guide and g[r][c] != bg]
    if not pts:
        return g
    colors = {(r, c): g[r][c] for r, c in pts}

    full_row = next((r for r in range(h) if all(v == guide for v in g[r])), None)
    if full_row is not None:
        minr = min(r for r, c in pts)
        maxr = max(r for r, c in pts)
        dr = full_row + 1 - minr if minr > full_row else full_row - 1 - maxr
        for r, c in pts:
            g[r][c] = bg
        moved = [(r + dr, c, color) for (r, c), color in colors.items()]
        for r, c, color in moved:
            if 0 <= r < h:
                g[r][c] = color
        far_row = max(r for r, c, _ in moved) + 1 if minr > full_row else min(r for r, c, _ in moved) - 1
        if 0 <= far_row < h:
            g[far_row] = [8] * w
        return g

    full_col = next((c for c in range(w) if all(g[r][c] == guide for r in range(h))), None)
    if full_col is not None:
        minc = min(c for r, c in pts)
        maxc = max(c for r, c in pts)
        dc = full_col + 1 - minc if minc > full_col else full_col - 1 - maxc
        for r, c in pts:
            g[r][c] = bg
        moved = [(r, c + dc, color) for (r, c), color in colors.items()]
        for r, c, color in moved:
            if 0 <= c < w:
                g[r][c] = color
        far_col = max(c for r, c, _ in moved) + 1 if minc > full_col else min(c for r, c, _ in moved) - 1
        if 0 <= far_col < w:
            for r in range(h):
                g[r][far_col] = 8
    return g
